create table public.stores(id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, status text not null default 'active', created_at timestamptz default now());
alter table public.stores enable row level security;
grant usage on schema public to anon, authenticated, service_role;
grant all on public.stores to service_role;
grant select on public.stores to anon, authenticated;
create policy public_can_read_active_stores on public.stores for select to anon,authenticated using(status='active');
create table public.products(id uuid primary key default gen_random_uuid(), store_id uuid references public.stores(id), status text);
alter table public.products enable row level security;
grant select on public.products to anon, authenticated;
create policy public_can_read_active_products on public.products for select to anon,authenticated using(status='active');
create table public.store_legal_documents(id uuid primary key default gen_random_uuid(), store_id uuid references public.stores(id), status text);
alter table public.store_legal_documents enable row level security;
grant select on public.store_legal_documents to anon,authenticated;
create policy public_can_read_published_store_legal_documents on public.store_legal_documents for select to anon,authenticated using(status='published');
create table public.platform_users(user_id uuid primary key references auth.users(id), role text not null check(role in ('platform_owner','platform_admin')));
create table public.store_memberships(id uuid primary key default gen_random_uuid(), store_id uuid references public.stores(id), user_id uuid references auth.users(id), role text not null, unique(store_id,user_id));
create table public.price_lists(id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id), name text not null, code text not null, customer_type text not null default 'pf', status text not null default 'active', currency text not null default 'BRL', priority integer not null default 0, is_default boolean not null default false, automatic_discount_enabled boolean not null default false, automatic_discount_percentage numeric default 10, promotion_policy text default 'best_price', unique(store_id,code));
alter table public.price_lists enable row level security;
grant all on public.price_lists to service_role;
